/* Growth OS: business-launch journey screens (My Business, Market Research, Suppliers, Financial Plan, Procurement, Launch Roadmap, Offers and campaigns). Every figure comes from the HTTP API; calculations run on the server from
   stored data. SYNTHETIC demo: nothing can be ordered, sent, published or paid for, and no supplier is contacted. Business and Engineering views read the same records. */
(()=>{'use strict';
const G=window.GOS,{api,act,page,esc,money,chip,stateChip,fmtTime,fmtDate,eng,tech,$,$$,toast}=G;
const role=()=>G.S().role,user=()=>G.S().user;
const can={launch:()=>['OWNER','ANALYST'].includes(role()),owner:()=>role()==='OWNER'};
const STAGES=[['idea','Idea'],['research','Research'],['sourcing','Suppliers'],['financial_plan','Financial plan'],['roadmap','Launch roadmap']];
const BASIS={founder:['Founder input','ok'],synthetic_assumption:['Synthetic assumption','warn'],public_reference:['Public reference','info']};
const KIND={search_result:'Public search result',synthetic_fixture:'Synthetic fixture',founder_note:'Founder note',public_source:'Public source',official_site:'Official site'};
const VER={synthetic_fixture:['Synthetic fixture','warn'],lead_unverified:['Lead, not verified','warn'],verified_public:['Verified from public sources','ok'],stale:['Stale','bad']};
const PCLASS={SYNTHETIC_QUOTE:['Synthetic quote','warn'],PUBLIC_REFERENCE:['Public reference','info'],SUPPLIER_QUOTE:['Supplier quote','ok'],NONE_PUBLISHED:['No published price','bad']};
const SRCK={official_site:'Official site',contact_page:'Contact page',trade_directory:'Trade directory',press:'Press',investor_profile:'Investor profile',partner_listing:'Partner listing',government_record:'Government record',encyclopedia:'Encyclopedia (secondary)'};
const TIER={primary_page_read:'ok',official_domain_snippet:'warn',secondary_only:'warn',synthetic:'info',none:'bad'};
const RECUR={one_time:'one-time',per_week:'every week'},RKIND={equipment:'Equipment',service:'Service',consumable:'Consumable'};
const INFO={verified_supplier_information:['Verified from public sources','ok'],unverified_public_lead:['Unverified public-search lead','warn'],synthetic_fixture:['Synthetic fixture','warn'],stale_information:['Stale: re-verify','bad']};
const PCAT={published_price:'Published price',supplier_quote:'Supplier quote',synthetic_quotation:'Synthetic quotation'};
const AREA={explicit:['Names the project area','ok'],statewide:['Statewide','info'],none:['Does not name the project area','warn'],unknown:['Service area unclear','']};
const cls=c=>c.replace(/_/g,' ').replace(/^./,m=>m.toUpperCase());
const SIM='Simulated projection built on stated assumptions. It is not actual business performance.';
const cents=c=>c==null?'—':(c<0?'−':'')+money(Math.abs(c)),dc=c=>c==null?'—':(c<0?'−':'')+money(Math.abs(Math.round(c))),p1=v=>v==null?'—':(100*v).toFixed(1)+'%',num=(v,d=1)=>v==null?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:d});
const key=()=>sessionStorage.getItem('gos.project');
async function overview(){
  const ps=(await act(()=>api('GET','/projects')))?.items||[];let id=key();if(!ps.find(p=>p.id===id))id=ps[0]&&ps[0].id;if(id)sessionStorage.setItem('gos.project',id);
  const ov=id?await act(()=>api('GET','/projects/'+id)):null;return {ps,id,ov}}
const picker=(ps,id)=>ps.length>1?`<label class="projpick">Project <select id="projpick" aria-label="Project">${ps.map(p=>`<option value="${esc(p.id)}" ${p.id===id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`:'';
const wirePick=()=>{const s=$('#projpick');if(s)s.onchange=()=>{sessionStorage.setItem('gos.project',s.value);G.route()}};
const wk=n=>n+(Number(n)===1?' week':' weeks');
const empty=(t)=>page(t,'No business-launch project exists in this workspace yet.',`<div class="card"><p class="note">${can.owner()?'Create the first project from My Business.':'An owner can create a project.'}</p></div>`);
const stageTrack=cur=>`<ol class="track" aria-label="Launch stages">${STAGES.map(([k,l],i)=>`<li class="${STAGES.findIndex(s=>s[0]===cur)>i?'done':STAGES.findIndex(s=>s[0]===cur)===i?'now':''}"><b>${i+1}</b>${esc(l)}</li>`).join('')}</ol>`;
const basisChip=b=>{const x=BASIS[b]||[b,''];return chip(x[0],x[1])};

/* ---------------- My Business ---------------- */
async function business(){
  const {ps,id,ov}=await overview();if(!ov)return empty('My <em>Business</em>');
  const done=ov.milestones.filter(m=>m.status==='done').length,next=ov.milestones.find(m=>m.status!=='done');
  const pref=ov.shortlist.filter(s=>s.status!=='rejected').length;
  const [rr,hh]=await Promise.all([act(()=>api('GET','/procurement/runs?limit=50')),act(()=>api('GET','/projects/'+id+'/history'))]);const runs=((rr)||{items:[]}).items.filter(r=>r.project===ov.name),hist=((hh)||{items:[]}).items;
  const exec=runs.some(r=>r.state==='EXECUTED'),wait=runs.some(r=>r.state==='AWAITING_APPROVAL'),latest=runs.find(r=>r.state==='EXECUTED')||runs.find(r=>r.state==='AWAITING_APPROVAL')||runs[0];
  const J=[['Idea','Project created: '+ov.name,true,'#/business'],['Market research',ov.findings.length+' finding'+(ov.findings.length===1?'':'s')+' recorded',ov.findings.length>0,'#/research'],['Suppliers',pref+' on the shortlist',pref>0,'#/suppliers'],
    ['Financial plan',ov.scenarios.length?ov.scenarios.length+' scenario'+(ov.scenarios.length===1?'':'s')+' saved':'No scenario saved yet',ov.scenarios.length>0,'#/financial'],['Procurement recommendation',latest?latest.status_label||latest.state:'Not requested yet',runs.some(r=>['AWAITING_APPROVAL','EXECUTED','REJECTED'].includes(r.state)),'#/procurement'],
    ['Human approval',exec?'Approved and recorded (nothing was ordered)':wait?'Waiting for a different owner to decide':'Not started',exec,'#/procurement'],['Launch roadmap',done+' of '+ov.milestones.length+' milestones done',ov.milestones.length>0&&done===ov.milestones.length,'#/roadmap']];
  const firstOpen=J.findIndex(j=>!j[2]);
  const key6=['weekly_orders','items_per_order','rent_monthly_cents','labor_monthly_cents','capex_buildout_cents','startup_capex_cents','price_elasticity'].map(k=>ov.assumptions.find(a=>a.key===k)).filter(a=>a&&!(a.key==='startup_capex_cents'&&a.value===0));
  page(`My <em>Business</em>`,`${esc(ov.industry)} · ${esc(ov.location)}. ${ov.basis==='synthetic'?'A synthetic case study: every figure is a planning assumption or fixture, not a result.':'Founder-provided project.'}`,`${picker(ps,id)}
  <div class="card hero-card"><h2>${esc(ov.name)}</h2><p class="muted">${esc(ov.concept)}</p>${stageTrack(ov.stage)}</div>
  <div class="card" style="margin-top:14px"><h2>The launch journey</h2><ol class="list journey">${J.map((j,i)=>`<li>${chip(j[2]?'Done':i===firstOpen?'Next':'To do',j[2]?'ok':i===firstOpen?'warn':'')}<span><a href="${j[3]}"><b>${esc(j[0])}</b></a><br><span class="note">${esc(j[1])}</span></span></li>`).join('')}</ol><p class="note">Each step opens the screen where it is done. A step is marked done only when its record exists.</p></div>
  <div class="grid g4" style="margin-top:14px"><div class="card kpi"><b>${cents(ov.budget_cents)}</b><span>launch budget</span></div><div class="card kpi"><b>${esc(fmtDate(ov.launch_target))}</b><span>target launch date</span></div><div class="card kpi"><b>${done}/${ov.milestones.length}</b><span>milestones done</span></div><div class="card kpi"><b>${pref}</b><span>suppliers on the shortlist</span></div></div>
  <div class="grid g2" style="margin-top:14px"><div class="card"><h2>Next step</h2>${next?`<p><b>${esc(next.title)}</b></p><p class="note">${esc(next.phase.replace('_',' '))}${next.due?' · due '+esc(fmtDate(next.due)):''} · <a href="#/roadmap">open the roadmap</a></p>`:'<p class="note">Every milestone is done.</p>'}<h3 style="margin-top:16px">Where the numbers come from</h3><p class="note">Assumptions are labelled by origin. Calculations are done by the server from stored records, never typed into the page. <a href="#/settings">Data provenance</a></p></div>
  <div class="card"><h2>Key assumptions</h2><div class="tablewrap"><table><thead><tr><th>Assumption</th><th>Value</th><th>Origin</th></tr></thead><tbody>${key6.map(a=>`<tr><td>${esc(a.label)}</td><td>${a.unit.includes('cents')?cents(a.value):num(a.value,2)+' '+esc(a.unit)}</td><td>${basisChip(a.basis)}</td></tr>`).join('')}</tbody></table></div><p class="note"><a href="#/financial">Change assumptions in the Financial Plan</a></p></div></div>
  <div class="card" style="margin-top:14px"><h2>${esc(ov.profile.key==='hospitality'?'Stated requirements (in addition to recipes)':'What this '+esc(ov.profile.label.toLowerCase())+' needs')}</h2>${ov.requirements.length?`<div class="tablewrap"><table><thead><tr><th>Item</th><th>Type</th><th>Quantity</th><th>Recurrence</th></tr></thead><tbody>${ov.requirements.map(r=>`<tr><td>${esc(r.name)}${r.note?`<br><span class="note">${esc(r.note)}</span>`:''}</td><td>${esc(RKIND[r.kind]||r.kind)}</td><td>${num(r.qty,2)} ${esc(r.unit)}</td><td>${esc(RECUR[r.recurrence]||r.recurrence)}</td></tr>`).join('')}</tbody></table></div>`:`<p class="note">No requirements stated yet. Procurement ${ov.profile.key==='hospitality'?'is driven by recipes and anything stated here':'is driven only by what is stated here'}.</p>`}
    <p class="note">${esc(ov.profile.label)} profile: sales are counted as ${esc(ov.profile.demand_term)}; the product is a ${esc(ov.profile.product_term)}; suppliers considered: ${esc(ov.profile.supplier_focus)}. One-time needs are bought once; weekly needs scale with the period.</p>
    ${can.launch()?`<details><summary><b>Add a requirement</b></summary><form class="inline" id="rq" style="margin-top:12px"><label>Reference (lowercase, e.g. ${esc((ov.profile.requirement_examples[0]||'item').split(' (')[0].toLowerCase().replace(/[^a-z0-9]+/g,'-'))})<input name="ref" required pattern="[a-z0-9][a-z0-9._-]{1,59}" maxlength="60"></label><label>Name<input name="name" required minlength="2" maxlength="120"></label><label>Type<select name="kind">${Object.entries(RKIND).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label><label>Quantity<input name="qty" type="number" min="0.01" step="any" required></label><label>Unit<input name="unit" required maxlength="20" value="each"></label><label>Recurrence<select name="recurrence">${Object.entries(RECUR).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label><button class="btn pri">Add requirement</button></form></details>`:''}</div>
  <div class="card" style="margin-top:14px"><h2>Project history</h2>${hist.length?`<ul class="timeline">${hist.slice(-12).reverse().map(h=>`<li class="ok"><span class="mono">${esc(fmtTime(h.ts,true))}</span><span>${esc(h.summary)}${eng()?`<br><code>audit #${h.seq} · ${esc(h.action)}</code>`:''}</span></li>`).join('')}</ul><p class="note">Newest first, the last ${Math.min(12,hist.length)} of ${hist.length} recorded changes. Exactly what the audit log holds; nothing is inferred.</p>`:'<p class="note">No changes are recorded for this project yet.</p>'}</div>
  ${can.owner()?`<details class="card" style="margin-top:14px"><summary><b>Create a new launch project</b></summary><form class="inline" id="np" style="margin-top:12px"><label>Business name<input name="name" required maxlength="120"></label><label>Industry<input name="industry" required maxlength="60"></label><label>Location<input name="location" required maxlength="80"></label><label>Budget ($)<input name="budget" type="number" min="0" step="1000" required></label><label>Target launch date<input name="launch_target" type="date"></label><label style="grid-column:1/-1">Concept<textarea name="concept" required minlength="10" maxlength="800"></textarea></label><button class="btn pri">Create project</button></form></details>`:''}
  ${eng()?`<div class="card" style="margin-top:14px"><h2>Engineering record</h2><dl class="kv"><dt>Project id</dt><dd><code>${esc(ov.id)}</code></dd><dt>Basis</dt><dd><code>${esc(ov.basis)}</code></dd><dt>Scenarios saved</dt><dd>${ov.scenarios.length}</dd></dl>${tech(ov)}</div>`:''}`);
  const rq=$('#rq');if(rq)rq.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(rq));v.qty=+v.qty;const r=await act(()=>api('POST',`/projects/${id}/requirements`,v),'Requirement added');if(r)G.route()};
  wirePick();const f=$('#np');if(f)f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));const r=await act(()=>api('POST','/projects',{name:v.name,industry:v.industry,location:v.location,concept:v.concept,budget_cents:Math.round(+v.budget*100),launch_target:v.launch_target||null,basis:'founder_input'}),'Project created');if(r){sessionStorage.setItem('gos.project',r.id);G.route()}}}

/* ---------------- Market Research ---------------- */
async function research(){
  const {ps,id,ov}=await overview();if(!ov)return empty('Market <em>Research</em>');
  const by={};ov.findings.forEach(f=>(by[f.topic]=by[f.topic]||[]).push(f));
  page('Market <em>Research</em>','What is known, where it came from and how far to trust it. A finding from a web page is a lead to check, not a verified fact.',`${picker(ps,id)}
  ${Object.entries(by).map(([t,fs])=>`<h2 style="margin-top:20px">${esc(t)}</h2><div class="grid g2">${fs.map(f=>`<article class="card"><p>${esc(f.finding)}</p><p>${chip(KIND[f.source_kind]||f.source_kind,f.source_kind==='search_result'?'info':f.source_kind==='synthetic_fixture'?'warn':'ok')} <span class="note">confidence ${Math.round(100*f.confidence)}%</span><span class="meter"><i style="width:${100*f.confidence}%"></i></span></p>
    <p class="note"><b>Limitation:</b> ${esc(f.limitation)}</p>${f.source_url?`<p class="note">Source: <a href="${esc(f.source_url)}" rel="noopener noreferrer" target="_blank">${esc(f.source_url.replace('https://',''))}</a>${f.retrieved_on?' · retrieved '+esc(fmtDate(f.retrieved_on)):''}</p>`:'<p class="note">No external source (internal assumption or note).</p>'}${eng()?`<code>${esc(f.id)}</code>${tech(f)}`:''}</article>`).join('')}</div>`).join('')||'<div class="card"><p class="note">No findings yet.</p></div>'}
  ${can.launch()?`<details class="card" style="margin-top:20px"><summary><b>Add a finding</b></summary><form class="inline" id="nf" style="margin-top:12px"><label>Topic<input name="topic" required maxlength="80"></label><label>Kind<select name="source_kind"><option value="founder_note">Founder note</option><option value="synthetic_fixture">Synthetic fixture</option><option value="search_result">Public search result</option><option value="public_source">Public source</option></select></label><label>Confidence 0–1<input name="confidence" type="number" step="0.05" min="0" max="1" value="0.5"></label><label>Source URL (https, required for public kinds)<input name="source_url" type="url"></label><label>Retrieved on<input name="retrieved_on" type="date"></label><label style="grid-column:1/-1">Finding<textarea name="finding" required minlength="5" maxlength="600"></textarea></label><label style="grid-column:1/-1">Limitation (required)<input name="limitation" required minlength="5" maxlength="300"></label><button class="btn pri">Add finding</button></form></details>`:''}`);
  wirePick();const f=$('#nf');if(f)f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));['source_url','retrieved_on'].forEach(k=>{if(!v[k])v[k]=null});v.confidence=+v.confidence;const r=await act(()=>api('POST',`/projects/${id}/findings`,v),'Finding added');if(r)G.route()}}

/* ---------------- Suppliers ---------------- */
async function suppliers(){
  const {ps,id,ov}=await overview();if(!ov)return empty('<em>Suppliers</em>');
  const d=await act(()=>api('GET','/suppliers?project_id='+id));if(!d)return;
  const it=await act(()=>api('GET','/supplier-intelligence?project_id='+id)),IC=Object.fromEntries(((it&&it.cards)||[]).map(c=>[c.id,c]));
  const rows=d.items;let filt='',term='',all=false;
  page('<em>Suppliers</em>','A trustworthy supplier record says where each fact came from, when it was checked and what the prices can and cannot be used for. No supplier has been contacted and no price from a real supplier is stored. Only the suppliers that fit the industry of this business are matched to its needs.',`${picker(ps,id)}
  <div class="notice">Planning date ${esc(fmtDate(d.as_of))}. Real suppliers below are <b>research leads</b>: each shows its <b>evidence tier</b> (what was actually seen and how). None is verified from a page read, no contact details are stored, and no real price is recorded. Compared prices belong to <b>synthetic fixtures</b>.</div>
  <div id="cmp"></div>
  <div class="filters"><input id="ssrch" type="search" placeholder="Search suppliers" aria-label="Search suppliers" autocomplete="off"><select id="sver" aria-label="Filter by verification"><option value="">All records</option>${Object.entries(VER).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select><span class="note" id="scnt"></span></div><div id="slist" class="slist"></div>
  ${can.launch()?`<details class="card" style="margin-top:14px"><summary><b>Add a supplier record</b></summary><form class="inline" id="ns" style="margin-top:12px"><label>Name<input name="name" required maxlength="120"></label><label>Category<input name="category" required maxlength="80"></label><label>Service area<input name="service_area" required maxlength="160"></label><label>Verification<select name="verification_status"><option value="lead_unverified">Lead, not verified</option><option value="synthetic_fixture">Synthetic fixture</option></select></label><label>Source kind<select name="source_kind"><option value="search_result">Public search result</option><option value="synthetic_fixture">Synthetic fixture</option></select></label><label>Source URL (https; required for search results)<input name="source_url" type="url"></label><label style="grid-column:1/-1">Notes<input name="notes" maxlength="300"></label><label class="chk" style="grid-column:1/-1"><input type="checkbox" name="confirm_distinct"> I checked the directory: this is a different supplier (needed only if the system warns of a possible duplicate)</label><button class="btn pri">Add supplier</button></form><p class="note">Contact details cannot be stored: the database rejects e-mail addresses and phone numbers. Verification as "verified from public sources" needs an official website, a source and a date, and is not offered here.</p></details>`:''}`);
  const cmpDraw=()=>{if(!it){$('#cmp').innerHTML='';return}const q=it.quotes,rs=q.rows,show=all?rs:rs.slice(0,8),cats=[...new Set(rs.flatMap(r=>Object.keys(r.categories)))];
    const dup=it.duplicates;$('#cmp').innerHTML=`<div class="card" style="margin-bottom:14px"><h2>Compare quotes</h2><p class="note">${esc(q.rule)}. Prices are shown with their data category; an expired quote or a supplier with no published price is listed, never ranked.</p>
      <p>${Object.entries(it.price_categories).filter(([k])=>k!=='none_published').map(([k,v])=>chip(v,k==='synthetic_quotation'?'warn':'ok')).join(' ')} ${chip(it.price_categories.none_published,'bad')} <span class="note">Information categories: ${Object.values(it.information_categories).map(esc).join(' · ')}</span></p>
      ${rs.length?`<div class="tablewrap"><table><thead><tr><th>Ingredient</th>${cats.map(c=>`<th>${esc(PCAT[c]||c)}</th>`).join('')}<th>Not compared</th></tr></thead><tbody>${show.map(r=>`<tr><td>${esc(r.name)} <span class="note">per ${esc(r.unit)}</span></td>${cats.map(c=>`<td>${(r.categories[c]||[]).map(e=>`<div>${esc(e.supplier.replace(/ \(.*\)/,''))}: <b>${dc(e.unit_price_cents)}</b>${e.cheapest_in_category?' '+chip('lowest in category','ok'):''}</div>`).join('')||'—'}</td>`).join('')}<td class="note">${r.expired.length?r.expired.length+' expired':''}${r.expired.length&&r.unpriced.length?' · ':''}${r.unpriced.length?r.unpriced.length+' unpriced':''}${!r.expired.length&&!r.unpriced.length?'—':''}</td></tr>`).join('')}</tbody></table></div>${rs.length>8?`<button class="btn sm" type="button" id="cmpall">${all?'Show fewer':'Show all '+rs.length+' ingredients'}</button>`:''}`:'<p class="note">No quoted ingredients to compare.</p>'}
      ${dup.length?`<div class="notice" style="margin-top:12px"><b>Possible duplicate suppliers</b> (a person decides; nothing is merged automatically):<ul>${dup.map(x=>`<li>${esc(x.a_name)} and ${esc(x.b_name)}: ${esc(x.reasons.join('; '))}</li>`).join('')}</ul></div>`:'<p class="note">No probable duplicate suppliers were found.</p>'}</div>`;const b=$('#cmpall');if(b)b.onclick=()=>{all=!all;cmpDraw()}};
  const draw=()=>{const sh=rows.filter(s=>(!filt||s.verification_status===filt)&&(!term||JSON.stringify(s).toLowerCase().includes(term)));$('#scnt').textContent=`${sh.length} of ${rows.length} shown`;
    $('#slist').innerHTML=sh.map(s=>{const v=VER[s.verification_status]||[s.verification_status,''],ic=IC[s.id],ar=ic&&ic.area&&AREA[ic.area.level];return `<article class="card sup"><div class="suph"><div><h3>${esc(s.name)}</h3><p class="note">${esc(s.category)} · ${esc(s.service_area)}</p></div><div>${chip(v[0],v[1])} ${chip(s.freshness,s.freshness==='stale'?'bad':s.freshness==='fresh'?'ok':'')}</div></div>
      ${ic?`<p class="chips">${chip(cls(ic.classification.primary)+' (rule-based)','info')} ${ar?chip(ar[0],ar[1]):''} ${ic.evidence_tier_label?chip('Evidence: '+ic.evidence_tier_label,TIER[ic.evidence_tier]||''):''}</p>`:''}
      <p class="note">${s.website_url?`Official website: <a href="${esc(s.website_url)}" rel="noopener noreferrer" target="_blank">${esc(s.website_url.replace('https://',''))}</a>`:'Official website: not verified'} · Contact: ${esc(s.contact_channel)} · ${s.verified_on?'Checked '+esc(fmtDate(s.verified_on)):'Never verified'}</p>
      ${s.source_url?`<p class="note">Source: <a href="${esc(s.source_url)}" rel="noopener noreferrer" target="_blank">${esc(s.source_url.replace('https://',''))}</a> (${esc(KIND[s.source_kind]||s.source_kind)})</p>`:`<p class="note">Source: ${esc(KIND[s.source_kind]||s.source_kind)}</p>`}${s.notes?`<p class="muted">${esc(s.notes)}</p>`:''}
      <p>${s.priced_products?`${s.priced_products} priced item${s.priced_products>1?'s':''}`:'<b>No published prices</b>'} · ${can.launch()?`<label class="inl">Shortlist <select data-sl="${esc(s.id)}" aria-label="Shortlist status for ${esc(s.name)}"><option value="">not shortlisted</option>${['shortlisted','preferred','rejected'].map(o=>`<option ${s.shortlist_status===o?'selected':''}>${o}</option>`).join('')}</select></label>`:esc(s.shortlist_status||'not shortlisted')}</p>
      ${(s.sources||[]).length?`<details><summary>Public sources (${s.sources.length})</summary><ul class="list">${s.sources.map(x=>`<li>${chip(SRCK[x.kind]||x.kind,'info')}<span>${esc(x.claim)}<br><span class="note"><a href="${esc(x.url)}" rel="noopener noreferrer" target="_blank">${esc(x.url.replace('https://',''))}</a> · ${x.access==='search_snippet'?'search-result snippet only (page not opened)':'page read'} · seen ${esc(fmtDate(x.observed_on))}</span></span></li>`).join('')}</ul><p class="note">A directory or news mention shows a business exists and what it is said to do. It is not an official website, a price or a verification.</p></details>`:`<p class="note">No public sources recorded.</p>`}
      ${can.launch()&&s.verification_status!=='synthetic_fixture'?`<details><summary>Add a public source</summary><form class="inline srcf" data-sid="${esc(s.id)}"><label>Kind<select name="kind">${Object.entries(SRCK).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label><label>Page URL (https)<input name="url" type="url" required pattern="https://.+"></label><label>How was it seen?<select name="access"><option value="search_snippet">Search-result snippet only</option><option value="page_read">I opened and read the page</option></select></label><label>Date seen<input name="observed_on" type="date" required></label><label style="grid-column:1/-1">What the source says (no phone numbers or e-mail addresses)<input name="claim" required minlength="8" maxlength="400"></label><button class="btn sm">Add source</button></form></details>`:''}
      <details><summary>Products and prices (${s.products.length})</summary><div class="tablewrap"><table><thead><tr><th>Item</th><th>Price</th><th>Pack · lead · min</th><th>Valid to</th><th>Limitation</th></tr></thead><tbody>${s.products.slice(0,60).map(p=>`<tr><td>${esc(p.name)}</td><td>${p.price_class==='NONE_PUBLISHED'?chip(PCLASS[p.price_class][0],'bad'):`${dc(p.unit_price_cents)} / ${esc(p.unit)} ${chip(PCLASS[p.price_class][0],PCLASS[p.price_class][1])}`}</td><td>${p.pack_qty?num(p.pack_qty,2)+' '+esc(p.unit):'—'} · ${p.lead_days==null?'—':p.lead_days+' d'} · ${cents(p.min_order_cents)}</td><td>${p.valid_to?esc(fmtDate(p.valid_to)):'—'}</td><td class="note">${esc(p.limitation)}</td></tr>`).join('')}</tbody></table></div>${s.products.length>60?`<p class="note">First 60 of ${s.products.length} shown.</p>`:''}</details>${eng()?`<code>${esc(s.id)}</code>`:''}</article>`}).join('')||'<p class="note">No supplier matches.</p>';
    $$('[data-sl]').forEach(sel=>sel.onchange=async()=>{if(!sel.value)return;await act(()=>api('PUT',`/projects/${id}/suppliers/${sel.dataset.sl}`,{status:sel.value}),'Shortlist updated')});
    $$('form.srcf').forEach(fm=>fm.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(fm));const r=await act(()=>api('POST',`/suppliers/${fm.dataset.sid}/sources`,v),'Source added');if(r)G.route()})};
  $('#ssrch').oninput=e=>{term=e.target.value.toLowerCase();draw()};$('#sver').onchange=e=>{filt=e.target.value;draw()};draw();cmpDraw();wirePick();
  const f=$('#ns');if(f)f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));if(!v.source_url)v.source_url=null;if(!v.notes)v.notes=null;v.confirm_distinct=!!v.confirm_distinct;const r=await act(()=>api('POST','/suppliers',v),'Supplier record added');if(r)G.route()}}

/* ---------------- Financial Plan ---------------- */
const CTRL=[['price_change_pct','Price change (%)',-20,20,1,0],['cost_change_pct','Ingredient cost change (%)',-20,40,1,0],['weekly_orders','Guest orders per week',0,3000,10,null],['avg_discount_pct','Average discount (%)',0,30,0.5,null],['price_elasticity','Price elasticity (assumed)',-4,0,0.1,null],['capex_buildout_cents','Build-out ($)',0,100000000,1000,null],['working_capital_months','Working capital (months)',0,36,0.5,null],['contingency_pct','Contingency (%)',0,100,1,null]];
async function financial(){
  const {ps,id,ov}=await overview();if(!ov)return empty('Financial <em>Plan</em>');
  const A=Object.fromEntries(ov.assumptions.map(a=>[a.key,a]));let ctl={};
  const body=()=>{const o={};CTRL.forEach(([k])=>{if(ctl[k]!=null&&ctl[k]!==''){o[k]=(k==='price_change_pct'||k==='cost_change_pct')?ctl[k]/100:k.endsWith('_cents')?Math.round(100*ctl[k]):+ctl[k]}});return o};
  page('Financial <em>Plan</em>',`A simulated projection from the project's stored products, prices, unit costs and assumptions. ${SIM}`,`${picker(ps,id)}
  <div class="notice">${SIM} Demand, product mix and price elasticity are assumed, not measured.</div>
  <div class="card"><h2>What if…</h2><form class="inline" id="ctl">${CTRL.map(([k,l,mn,mx,st,dv])=>`<label>${l}<input name="${k}" type="number" min="${mn}" max="${mx}" step="${st}" placeholder="${k in A?(k.endsWith('_cents')?A[k].value/100:A[k].value):dv}" value="${ctl[k]??''}"></label>`).join('')}<button class="btn pri">Calculate</button><button class="btn" type="button" id="rst">Reset to stored assumptions</button></form><p class="note">Leave a box empty to use the stored assumption.</p></div><div id="fres" aria-live="polite"></div>
  <div class="card" style="margin-top:14px"><h2>Stored assumptions</h2><div class="tablewrap"><table><thead><tr><th>Assumption</th><th>Value</th><th>Origin</th>${can.launch()?'<th>Change</th>':''}</tr></thead><tbody>${ov.assumptions.map(a=>`<tr><td>${esc(a.label)}${a.note?`<br><span class="note">${esc(a.note)}</span>`:''}</td><td>${a.unit.includes('cents')?cents(a.value):num(a.value,2)+' '+esc(a.unit)}</td><td>${basisChip(a.basis)}</td>${can.launch()?`<td><form data-as="${esc(a.key)}" class="mini"><input name="v" type="number" step="any" value="${a.unit.includes('cents')?a.value/100:a.value}" aria-label="New value for ${esc(a.label)}"><button class="btn sm">Save</button></form></td>`:''}</tr>`).join('')}</tbody></table></div><p class="note">Saving a value records it as a founder input and the change is audited.${can.launch()?' Money fields are in dollars here.':''}</p></div>
  <div class="card" style="margin-top:14px"><h2>Saved scenarios</h2>${ov.scenarios.length?`<ul class="list">${ov.scenarios.map(s=>`<li><span>${esc(s.name)}</span><span class="note">${eng()?'<code>'+esc(s.inputs_hash.slice(0,16))+'</code> · ':''}saved ${esc(fmtTime(s.created_at))}</span></li>`).join('')}</ul>`:'<p class="note">None yet. Calculate a what-if, then save it.</p>'}</div>`);
  const show=async()=>{const r=await act(()=>api('POST',`/projects/${id}/scenarios/preview`,body()));if(!r)return;const x=r.results;
    const cmp=await act(()=>api('POST',`/projects/${id}/scenarios/compare`,{scenarios:[{name:'Stored assumptions'},{name:'Prices +5%',overrides:{price_change_pct:0.05}},{name:'Ingredient costs +20%',overrides:{cost_change_pct:0.2}},{name:'Orders −20%',overrides:{weekly_orders:(A.weekly_orders?A.weekly_orders.value:0)*0.8}}]}));
    const maxp=Math.max(1,...r.sensitivity.price.map(q=>Math.abs(q.operating_profit_monthly_cents)));
    $('#fres').innerHTML=`<div class="grid g4" style="margin-top:14px"><div class="card kpi"><b>${cents(x.revenue_cents)}</b><span>revenue / month</span></div><div class="card kpi"><b>${p1(x.gross_margin)}</b><span>gross margin</span></div><div class="card kpi"><b>${p1(x.contribution_margin)}</b><span>contribution margin</span></div><div class="card kpi ${x.operating_profit_monthly_cents<0?'neg':''}"><b>${cents(x.operating_profit_monthly_cents)}</b><span>operating profit / month</span></div></div>
    <div class="grid g2" style="margin-top:14px"><div class="card"><h2>Monthly projection</h2><dl class="kv"><dt>Units sold</dt><dd>${num(x.units_per_month,0)}</dd><dt>Revenue</dt><dd>${cents(x.revenue_cents)}</dd><dt>Variable costs (ingredients, fees)</dt><dd>${cents(x.variable_cost_cents)}</dd><dt>Contribution</dt><dd>${cents(x.contribution_cents)}</dd><dt>Fixed costs</dt><dd>${cents(x.fixed_costs_monthly_cents)}</dd><dt><b>Operating profit</b></dt><dd><b>${cents(x.operating_profit_monthly_cents)}</b></dd></dl></div>
    <div class="card"><h2>Break-even and payback</h2><dl class="kv"><dt>Break-even volume</dt><dd>${num(x.breakeven_units_per_month,0)} units / month (${num(x.breakeven_orders_per_week,0)} orders / week)</dd><dt>Plan vs break-even</dt><dd>${x.breakeven_vs_plan?num(x.breakeven_vs_plan,2)+'×':'—'}</dd><dt>Capital items only</dt><dd>${cents(x.startup_capex_cents)}</dd><dt>Budget after capital items (before other start-up costs)</dt><dd>${cents(x.budget_after_capex_cents)}</dd><dt>Payback</dt><dd>${x.payback_months==null?'not within the projection':num(x.payback_months,0)+' months'}</dd>${x.runway_months_if_loss_making!=null?`<dt>Runway if loss-making</dt><dd>${num(x.runway_months_if_loss_making,1)} months</dd>`:''}</dl>${can.launch()?'<button class="btn" id="svs" type="button">Save this scenario</button>':''}</div></div>
    ${(()=>{const st=x.startup,ok=st.budget_covers_requirement,rows=[...Object.entries(st.capex).map(([k,v])=>['Capital expenditure',k,v]),...Object.entries(st.preopening).map(([k,v])=>['Pre-opening',k,v]),['Working capital',st.working_capital.fixed_cost_months+' months of fixed costs',st.working_capital.fixed_cost_cents],['Working capital',st.working_capital.opening_inventory_weeks+' weeks of opening inventory (modelled cost of goods)',st.working_capital.opening_inventory_cents]];
      return `<div class="card" style="margin-top:14px"><h2>Start-up costs</h2><p>${ok?chip('Budget covers the plan','ok'):chip('Budget does not cover the plan','bad')} <b>${cents(st.total_requirement_cents)}</b> needed against a <b>${cents(st.budget_cents)}</b> budget: ${ok?'headroom '+cents(st.headroom_cents):'gap of '+cents(st.funding_gap_cents)}.</p><div class="tablewrap"><table><thead><tr><th>Category</th><th>Item</th><th>Amount</th></tr></thead><tbody>${rows.map(([c,k,v])=>`<tr><td>${esc(c)}</td><td>${esc(k)}</td><td>${cents(v)}</td></tr>`).join('')}<tr><td colspan="2"><b>Subtotal</b></td><td><b>${cents(st.subtotal_cents)}</b></td></tr><tr><td colspan="2">Contingency (${num(st.contingency_pct,1)}% of the subtotal)</td><td>${cents(st.contingency_cents)}</td></tr><tr><td colspan="2"><b>Total start-up requirement</b></td><td><b>${cents(st.total_requirement_cents)}</b></td></tr></tbody></table></div><p class="note">Every line is a stored assumption you can change below; none is a quote. ${ok?'':'Closing the gap means a larger budget or smaller costs: try the build-out or contingency boxes in What if.'}</p></div>`})()}
    <div class="card" style="margin-top:14px"><h2>Unit economics by product</h2><div class="tablewrap"><table><thead><tr><th>Product</th><th>Price after discount</th><th>Unit cost</th><th>Gross margin</th><th>Contribution margin</th><th>Mix</th><th>Units / month</th></tr></thead><tbody>${x.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${dc(l.price_cents)}</td><td>${dc(l.unit_cost_cents)}</td><td>${p1(l.gross_margin)}</td><td>${p1(l.contribution_margin)}</td><td>${p1(l.mix)}</td><td>${num(l.units_per_month,0)}</td></tr>`).join('')}</tbody></table></div><p class="note">Prices are the stored current prices (concept prices for the flagship case study); unit costs are planning assumptions, not supplier quotes.</p></div>
    <div class="grid g2" style="margin-top:14px"><div class="card"><h2>Price sensitivity</h2><div class="bars">${r.sensitivity.price.map(q=>`<div class="bar"><span>${q.price_change_pct>0?'+':''}${q.price_change_pct}%</span><i><b style="width:${100*Math.abs(q.operating_profit_monthly_cents)/maxp}%;${q.operating_profit_monthly_cents<0?'background:var(--bad)':''}"></b></i><span class="mono">${dc(q.operating_profit_monthly_cents/1)} / mo</span></div>`).join('')}</div><p class="note">Uses the stated elasticity (${r.sensitivity.elasticity_assumed}), an assumption: no willingness-to-pay data exists.</p></div>
    <div class="card"><h2>Ingredient cost changes</h2><div class="tablewrap"><table><thead><tr><th>Cost change</th><th>Gross margin</th><th>Operating profit / mo</th><th>Break-even units</th></tr></thead><tbody>${r.sensitivity.cost.map(q=>`<tr><td>+${q.cost_change_pct}%</td><td>${p1(q.gross_margin)}</td><td>${cents(q.operating_profit_monthly_cents)}</td><td>${num(q.breakeven_units_per_month,0)}</td></tr>`).join('')}</tbody></table></div></div></div>
    ${cmp?`<div class="card" style="margin-top:14px"><h2>Scenario comparison</h2><div class="tablewrap"><table><thead><tr><th>Scenario</th><th>Revenue / mo</th><th>Gross margin</th><th>Operating profit / mo</th><th>Difference from stored</th><th>Break-even units</th></tr></thead><tbody>${cmp.rows.map(q=>`<tr><td>${esc(q.name)}</td><td>${cents(q.revenue_cents)}</td><td>${p1(q.gross_margin)}</td><td>${cents(q.operating_profit_monthly_cents)}</td><td>${q.profit_vs_base_cents>0?'+':''}${cents(q.profit_vs_base_cents)}</td><td>${num(q.breakeven_units_per_month,0)}</td></tr>`).join('')}</tbody></table></div></div>`:''}
    <div class="grid g2" style="margin-top:14px"><div class="card"><h2>Break-even orders per week</h2><div class="tablewrap"><table><thead><tr><th>Ingredient cost ↓ / price →</th>${r.breakeven_grid.price_changes_pct.map(p=>`<th>${p>0?'+':''}${p}%</th>`).join('')}</tr></thead><tbody>${r.breakeven_grid.rows.map(w=>`<tr><td>${w.cost_change_pct>0?'+':''}${w.cost_change_pct}%</td>${w.cells.map(c=>`<td>${c.breakeven_orders_per_week==null?'<span class="note">not reachable</span>':num(c.breakeven_orders_per_week,0)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">${esc(r.breakeven_grid.note)}</p></div>
    <div class="card"><h2>What this model does not know</h2><ul class="limits">${r.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></div></div>
    <details class="card" style="margin-top:14px"><summary><b>Formulas: how each number is calculated</b></summary><ul class="list">${x.formulas.map(f=>`<li><span><b>${esc(f.name)}</b><br><span class="note">${esc(f.formula)}</span><br>${esc(f.worked)}</span></li>`).join('')}</ul><p class="note">The numbers in these lines are the stored inputs substituted into each formula; the same inputs always give the same results.</p></details>
    ${eng()?`<div class="card" style="margin-top:14px"><h2>Engineering record</h2><dl class="kv"><dt>Inputs hash</dt><dd><code>${esc(r.inputs_hash)}</code></dd><dt>Defaulted assumptions</dt><dd>${esc(r.inputs.defaulted_assumptions.join(', ')||'none')}</dd></dl>${tech(r.inputs)}</div>`:''}`;
    const sv=$('#svs');if(sv)sv.onclick=async()=>{const n=prompt('Name for this scenario','Scenario');if(!n)return;await act(()=>api('POST',`/projects/${id}/scenarios`,{name:n,overrides:body()}),'Scenario saved');G.route()}};
  const f=$('#ctl');f.onsubmit=async e=>{e.preventDefault();ctl=Object.fromEntries(new FormData(f));await show()};$('#rst').onclick=()=>{ctl={};f.reset();show()};
  $$('form.mini').forEach(m=>m.onsubmit=async e=>{e.preventDefault();const k=m.dataset.as,a=A[k],v=+new FormData(m).get('v');await act(()=>api('PUT',`/projects/${id}/assumptions/${k}`,{label:a.label,value:a.unit.includes('cents')?Math.round(v*100):v,unit:a.unit,basis:'founder',note:'Changed in the Financial Plan'}),'Assumption saved');G.route()});
  wirePick();await show()}

/* ---------------- Procurement ---------------- */
async function procurement(rid){ if(rid)return procDetail(rid);
  const {ps,id,ov}=await overview();if(!ov)return empty('<em>Procurement</em>');
  const runs=await act(()=>api('GET','/procurement/runs?limit=30'));if(!runs)return;
  const cols=[['Project',r=>`<b>${esc(r.project)}</b><br><span class="note">${esc(String(r.period).replace(/^1 weeks$/,"1 week"))}</span>`],['Status',r=>stateChip(r.state)],['Planned spend',r=>cents(r.total_cost_cents)],['Research',r=>`<span class="note">${esc(r.agent||'—')}</span>`],['Requested by',r=>esc(r.requested_by)],['Last activity',r=>esc(fmtTime(r.last_activity||r.created_at))],...(eng()?[['Record',r=>`<code>${esc(r.id)}${r.failure?'<br>'+esc(r.failure):''}</code>`]]:[]),['',r=>`<a class="btn sm" href="#/procurement/${esc(r.id)}">Open</a>`]];
  page('<em>Procurement</em>','A procurement recommendation compares stored supplier quotes for the ingredients the plan needs. An agent prepares a cited research brief, THE WEIR holds the record, and a different owner decides. Nothing is ordered and no supplier is contacted.',`${picker(ps,id)}
  <div class="card"><h2>Request a recommendation</h2>${can.launch()?`<form class="inline" id="pq"><label>Planning period (weeks)<input name="period_weeks" type="number" min="1" max="26" value="4"></label><button class="btn pri">Prepare recommendation</button></form>`:'<p class="note">Your role cannot request a recommendation (THE WEIR has no write tool for this role).</p>'}</div>
  <h2 style="margin-top:20px">Recommendations</h2><div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th>${c[0]}</th>`).join('')}</tr></thead><tbody>${runs.items.map(r=>`<tr>${cols.map(c=>`<td>${c[1](r)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="8" class="note">None yet.</td></tr>'}</tbody></table></div>`);
  wirePick();const f=$('#pq');if(f)f.onsubmit=async e=>{e.preventDefault();const r=await act(()=>api('POST',`/projects/${id}/procurement`,{period_weeks:+new FormData(f).get('period_weeks')}),'Recommendation prepared and held for approval');if(r)location.hash=`#/procurement/${r.corr_id}`}}
async function procDetail(rid){
  const r=await act(()=>api('GET','/procurement/runs/'+rid));if(!r){location.hash='#/procurement';return}
  const b=r.business,s=b.summary,rec=b.recommendation,rs=b.research,ap=b.approval,mine=r.requester===user(),canDecide=ap.can_decide&&role()==='OWNER'&&!mine;
  const note=!ap.can_decide?'':role()!=='OWNER'?'Only an owner may approve or reject this recommendation.':mine?'You requested this, so a different owner must decide (two-person rule).':'';
  const closed={EXECUTED:'The decision is recorded and the recommendation was recorded once. Nothing was ordered.',REJECTED:'Rejected. Nothing was recorded.',BLOCKED:'Nothing can be approved: the run was blocked before a recommendation could be recorded.',FAILED:'Nothing can be approved: the run failed and nothing was recorded.'}[r.state]||'';
  page(`Procurement: <em>${esc(s.project||'')}</em>`,`${esc(s.period)} · ${stateChip(r.state)}`,`
  <div class="grid g2"><div class="card"><h2>Summary</h2><dl class="kv"><dt>Objective</dt><dd>${esc(s.objective)}</dd><dt>Status</dt><dd>${stateChip(r.state)}</dd><dt>Requested by</dt><dd>${esc(s.requested_by)}</dd><dt>Last activity</dt><dd>${esc(fmtTime(s.last_activity))}</dd><dt>Outcome</dt><dd><b>${esc(s.outcome)}</b></dd>${rec?`<dt>Planned spend</dt><dd><b>${cents(rec.total_cost_cents)}</b> over ${wk(rec.period_weeks)}</dd>`:''}</dl></div>
  <div class="card"><h2>Research brief</h2>${rs?`<p>${rs.mode==='deterministic_fallback'?chip('No agent ran','warn'):rs.model_backed?chip('Language-model assisted','ok'):chip('Offline heuristic: not a language model','info')}</p><p class="note">${esc(rs.mode_label)}.${rs.fallback_reason?' Reason: '+esc(rs.fallback_reason)+'.':''}</p><p class="note">${rs.model_backed?'A language model produced this brief and it passed the checks below.':'No language model was used for this brief.'}</p>${rs.rejected?`<div class="notice"><b>The agent output was discarded:</b> ${esc(rs.rejected_reasons.join('; ')||'it failed verification')}. The recommendation below is unaffected.</div>`:''}<ul class="limits">${rs.claims.slice(0,8).map(c=>`<li>${esc(c)}</li>`).join('')||'<li>No claims.</li>'}</ul>${rs.boundary==='accepted'?'<p class="note">Checked: every claim cites a stored source, every number appears in it, and no tool beyond reading was used.</p>':''}<p class="note">The brief informs the reviewer. Every number in the recommendation is calculated from stored quotes and independently re-derived; none is taken from agent text.</p>${rs.uncertainty&&rs.uncertainty.length?`<h3>What remains uncertain</h3><ul class="limits">${rs.uncertainty.map(u=>`<li>${esc(u)}</li>`).join('')}</ul>`:''}${rs.limitations.map(l=>`<p class="note">${esc(l)}</p>`).join('')}`:'<p class="note">No research was produced.</p>'}</div></div>
  ${rec?`<div class="card" style="margin-top:14px"><h2>Recommended quotes by supplier</h2>${rec.flags.map(f=>`<div class="notice">${esc(f.message)}</div>`).join('')}${rec.price_effect?`<p class="note"><b>Effect of the supplier choice:</b> buying each ingredient from its second-cheapest valid quote would cost ${cents(rec.price_effect.difference_cents)} more over this period (about ${cents(rec.price_effect.monthly_equivalent_difference_cents)} a month). ${esc(rec.price_effect.note)}</p>`:''}${rec.suppliers.map(sp=>`<h3 style="margin-top:12px">${esc(sp.supplier)} · ${cents(sp.cost_cents)} · ${sp.items} items ${sp.below_minimum_order?chip('below minimum order','bad'):''}</h3><div class="tablewrap"><table><thead><tr><th>Ingredient</th><th>Need</th><th>Buy</th><th>Cost</th><th>Lead</th><th>Next best</th></tr></thead><tbody>${sp.lines.slice(0,12).map(l=>`<tr><td>${esc(l.ingredient)}</td><td>${num(l.need,l.need<1?3:2)} ${esc(l.unit)}</td><td>${num(l.buy_qty,2)} ${esc(l.unit)}</td><td>${cents(l.cost_cents)}</td><td>${l.lead_days} d</td><td class="note">${l.runner_up?esc(l.runner_up.supplier)+' '+cents(l.runner_up.cost_cents):'only quote'}</td></tr>`).join('')}</tbody></table></div>${sp.lines.length>12?`<p class="note">Top 12 of ${sp.lines.length} by cost.</p>`:''}`).join('')}<p class="note">${esc(rec.disclaimer)} Prices: ${esc(rec.suppliers.flatMap(x=>x.price_classes).filter((v,i,a)=>a.indexOf(v)===i).map(c=>(PCLASS[c]||[c])[0]).join(', '))}.</p></div>
  <div class="card" style="margin-top:14px"><h2>Inventory planning</h2><div class="tablewrap"><table><thead><tr><th>Ingredient</th><th>Weekly use</th><th>Supplier lead time</th><th>Reorder point</th><th>One order covers</th></tr></thead><tbody>${rec.replenishment.slice(0,12).map(x=>`<tr><td>${esc(x.ingredient)}</td><td>${num(x.weekly_usage,2)} ${esc(x.unit)}</td><td>${x.lead_days} days</td><td>${num(x.reorder_point,2)} ${esc(x.unit)}</td><td>${x.weeks_covered==null?'—':num(x.weeks_covered,1)+' weeks'}</td></tr>`).join('')}</tbody></table></div><p class="note">Shortest cover first. Reorder points use the chosen supplier's lead time and a safety margin that is an assumption (${esc(rec.replenishment_assumption||'')}).</p></div>`:''}
  <div class="grid g2" style="margin-top:14px"><div class="card"><h2>Authorization</h2>${b.authorization.length?`<ul class="timeline">${b.authorization.map(a=>`<li class="${({ok:'ok',no:'bad',wait:'hold'})[a.tone]||''}"><span class="mono">${a.tone==='no'?'Blocked':a.tone==='wait'?'Held':a.tone==='ok'?'Allowed':'Info'}</span><span><b>${esc(a.title)}</b>${a.detail?`<br><span class="muted">${esc(a.detail)}</span>`:''}${tech(a.technical)}</span></li>`).join('')}</ul>`:'<p class="note">No authorization decisions were recorded.</p>'}</div>
  <div class="card"><h2>Approval</h2><p>${stateChip(r.state)}</p><dl class="kv"><dt>Requested by</dt><dd>${esc(ap.requested_by)}</dd>${ap.decided_by?`<dt>Decided by</dt><dd>${esc(ap.decided_by)}</dd>`:''}${ap.comment?`<dt>Comment</dt><dd>${esc(ap.comment)}</dd>`:''}</dl>${rec?`<p class="note">Approving records exactly this recommendation once. It does not place an order.</p>`:''}${canDecide?`<div class="actions"><button class="btn pri" id="ap">Approve and record</button><button class="btn" id="rj">Reject</button></div>`:`<p class="note">${esc(note||closed)}</p>`}</div></div>
  <div class="card" style="margin-top:14px"><h2>Timeline <small class="note">(only events that were recorded)</small></h2><ul class="timeline">${b.timeline.map(t=>`<li class="${({ok:'ok',no:'bad',wait:'hold'})[t.tone]||''}"><span class="mono">${esc(fmtTime(t.ts,true))}</span><span><b>${esc(t.title)}</b>${t.detail?`<br><span class="muted">${esc(t.detail)}</span>`:''}${eng()?`<br><code>event #${t.seq} · ${esc(t.technical.kind)}${t.technical.stage?' · '+esc(t.technical.stage):''}</code>`+tech(t.technical):''}</span></li>`).join('')}</ul></div>
  ${eng()?`<div class="card" style="margin-top:14px"><h2>Engineering record</h2><dl class="kv"><dt>Run id</dt><dd><code>${esc(r.id)}</code></dd><dt>Project id</dt><dd><code>${esc(r.project_id)}</code></dd><dt>Approval id</dt><dd><code>${esc(r.approval_id||'—')}</code></dd><dt>Agent mode</dt><dd><code>${esc(r.agent_mode||'—')}</code></dd><dt>Failure class</dt><dd><code>${esc(r.failure||'—')}</code></dd></dl>${r.research?`<details open class="tech"><summary>Research (raw JSON)</summary><pre>${esc(JSON.stringify(r.research,null,1))}</pre></details>`:''}</div>`:''}`);
  const decide=async ok=>{const c=prompt(ok?'Approval comment (optional)':'Reason for rejecting','')??'';const d=await act(()=>api('POST',`/procurement/runs/${rid}/decision`,{approve:ok,comment:c},{idem:false}),ok?'Approved and recorded':'Rejected');if(d)procDetail(rid)};
  if($('#ap')){$('#ap').onclick=()=>decide(true);$('#rj').onclick=()=>decide(false)}}

/* ---------------- Launch Roadmap ---------------- */
async function roadmap(){
  const {ps,id,ov}=await overview();if(!ov)return empty('Launch <em>Roadmap</em>');
  const done=ov.milestones.filter(m=>m.status==='done').length,pct=ov.milestones.length?Math.round(100*done/ov.milestones.length):0;
  page('Launch <em>Roadmap</em>',`Milestones by phase toward the target date ${esc(fmtDate(ov.launch_target))}. Dates are plans, not commitments.`,`${picker(ps,id)}
  <div class="card"><h2>${done} of ${ov.milestones.length} milestones done</h2><div class="gauge" role="img" aria-label="${pct}% of milestones done"><i style="width:${pct}%"></i></div>${stageTrack(ov.stage)}</div>
  ${STAGES.map(([k,l])=>{const ms=ov.milestones.filter(m=>m.phase===k);return ms.length?`<h2 style="margin-top:20px">${l}</h2><ul class="list">${ms.map(m=>`<li>${chip(m.status==='done'?'Done':m.status==='doing'?'In progress':'To do',m.status==='done'?'ok':m.status==='doing'?'warn':'')}<span><b>${esc(m.title)}</b><br><span class="note">${m.due?'Due '+esc(fmtDate(m.due)):'No date'}${m.note?' · '+esc(m.note):''}${eng()?' · <code>'+esc(m.id)+'</code>':''}</span></span>${can.owner()?`<select data-ms="${esc(m.id)}" aria-label="Status of ${esc(m.title)}">${['todo','doing','done'].map(s=>`<option value="${s}" ${m.status===s?'selected':''}>${({todo:'To do',doing:'In progress',done:'Done'})[s]}</option>`).join('')}</select>`:''}</li>`).join('')}</ul>`:''}).join('')}
  ${can.owner()?`<details class="card" style="margin-top:20px"><summary><b>Add a milestone</b></summary><form class="inline" id="nm" style="margin-top:12px"><label>Title<input name="title" required minlength="3" maxlength="160"></label><label>Phase<select name="phase">${STAGES.map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label><label>Due<input name="due" type="date"></label><button class="btn pri">Add</button></form></details>`:''}`);
  wirePick();$$('[data-ms]').forEach(s=>s.onchange=async()=>{await act(()=>api('PUT',`/milestones/${s.dataset.ms}/status`,{status:s.value}),'Milestone updated');G.route()});
  const f=$('#nm');if(f)f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));if(!v.due)v.due=null;const r=await act(()=>api('POST',`/projects/${id}/milestones`,v),'Milestone added');if(r)G.route()}}

/* ---------------- Offers and campaigns ---------------- */
async function marketing(){
  const d=await act(()=>api('GET','/marketing/offers'));if(!d)return;
  page('Offers and <em>campaigns</em>','Draft offers and the arithmetic behind them, from stored prices and costs. Nothing here is published, sent or paid for.',`
  <div class="card"><h2>Offer economics</h2>${d.offers.length?`<div class="tablewrap"><table><thead><tr><th>Offer</th><th>Product</th><th>Discount</th><th>Price</th><th>Margin before → after</th><th>Volume uplift needed to hold profit</th><th>Status</th></tr></thead><tbody>${d.offers.map(o=>`<tr><td>${esc(o.name)}<br><span class="note">${esc(fmtDate(o.starts))} to ${esc(fmtDate(o.ends))}</span></td><td>${esc(o.product)}</td><td>${o.discount_pct}%</td><td>${cents(o.price_cents)}</td><td>${p1(o.margin_before)} → ${p1(o.margin_after)}</td><td>${o.breakeven_volume_uplift==null?'cannot break even':'+'+p1(o.breakeven_volume_uplift)}</td><td>${chip(o.status,'info')}</td></tr>`).join('')}</tbody></table></div><p class="note">${esc(d.note)}</p>`:'<p class="note">No offers are drafted in this workspace.</p>'}</div>
  <div class="card" style="margin-top:14px"><h2>Campaign drafts</h2>${d.campaigns.length?`<ul class="list">${d.campaigns.map(c=>`<li>${chip(c.status,'info')}<span><b>${esc(c.name)}</b><br><span class="note">Offer: ${esc(c.offer||'—')} · Audience: ${esc(c.segment||'—')}</span></span></li>`).join('')}</ul>`:'<p class="note">No campaign drafts.</p>'}<p class="note">There is no send, publish or ad-spend operation in this application.</p></div>`)}

Object.assign(G.ROUTES,{business,research,suppliers,financial,procurement,roadmap,marketing});
G.boot();
})();
